create table if not exists public.conversation_groups(conversation_id bigint primary key references public.conversations(id) on delete cascade,name text not null,description text not null default '',avatar_url text,owner_id bigint not null references public.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.group_members(conversation_id bigint not null references public.conversations(id) on delete cascade,user_id bigint not null references public.users(id) on delete cascade,role text not null default 'member',joined_at timestamptz,left_at timestamptz,primary key(conversation_id,user_id));
create table if not exists public.call_sessions(id bigint generated by default as identity primary key,conversation_id bigint references public.conversations(id) on delete set null,caller_id bigint not null references public.users(id) on delete cascade,call_type text not null,status text not null default 'ringing',started_at timestamptz not null default now(),answered_at timestamptz,ended_at timestamptz,duration_seconds integer not null default 0,created_at timestamptz not null default now());
create table if not exists public.call_participants(call_id bigint not null references public.call_sessions(id) on delete cascade,user_id bigint not null references public.users(id) on delete cascade,status text not null,joined_at timestamptz,left_at timestamptz,primary key(call_id,user_id));
create table if not exists public.call_signals(id bigint generated by default as identity primary key,call_id bigint not null references public.call_sessions(id) on delete cascade,sender_id bigint not null references public.users(id) on delete cascade,kind text not null,payload jsonb not null,created_at timestamptz not null default now());
create index if not exists call_signals_call_idx on public.call_signals(call_id,id);
create table if not exists public.message_devices(id bigint generated by default as identity primary key,user_id bigint not null references public.users(id) on delete cascade,device_id text not null,public_key text not null,label text,created_at timestamptz not null default now(),last_seen_at timestamptz not null default now(),revoked_at timestamptz,unique(user_id,device_id));
alter table public.messages add column if not exists encryption_version integer;
alter table public.messages add column if not exists sender_device_id text;
create table if not exists public.call_load_test_runs(id bigint generated by default as identity primary key,label text not null,clients integer not null,duration_seconds integer not null,reconnects integer not null default 0,failures integer not null default 0);